// Some portions generated by Claude Code

// Cleanup of stored query results ("maintenance"). Each stored result is its own IndexedDB database, listed in a
// localStorage registry with its size. Cleanup runs only in a visible tab, one tab at a time, and never deletes a
// store whose page still holds its Web Lock: a hidden tab can be frozen by the browser at any moment, and IndexedDB
// work it started would then stay unfinished and hold other tabs up.

const test = require('node:test');
const assert = require('node:assert/strict');
const { loadApi } = require('./query-load-more-harness.js');

const REGISTRY = 'rdf4j.workbench.row-store.v2:';
const DATABASE = 'rdf4j-workbench-row-store:';
const LOCK = 'rdf4j-workbench-row-store:';
const MAINTAINED = 'rdf4j.workbench.row-store.v2.maintained';
const LEGACY_DATABASE = 'rdf4j-workbench-query-results';
const LEGACY_MARKER = 'rdf4j.workbench.query-results.pending-disposal.v1:';
const LEGACY_LOCK = 'rdf4j-workbench-query-rows:';
const HOUR = 60 * 60 * 1000;
const DAY = 24 * HOUR;
const NOW = Date.UTC(2026, 9, 7, 9, 0, 0);

function idAt(time, suffix) {
    return 'rows-' + time.toString(36) + '-' + suffix;
}

function mapStorage() {
    const values = new Map();
    return {
        values,
        get length() { return values.size; },
        key(index) { return [...values.keys()][index] || null; },
        getItem(key) { return values.has(key) ? values.get(key) : null; },
        setItem(key, value) { values.set(key, String(value)); },
        removeItem(key) { values.delete(key); }
    };
}

function register(storage, id, entry) {
    storage.setItem(REGISTRY + id, JSON.stringify(entry));
}

function entryOf(storage, id) {
    const value = storage.getItem(REGISTRY + id);
    return value === null ? null : JSON.parse(value);
}

/** An IndexedDB factory with named databases; behaviour makes a name's deletion block, stay silent or fail. */
function fakeIndexedDB(names = []) {
    const databases = new Set(names);
    const attempts = [];
    const behaviour = new Map();
    return {
        databases,
        attempts,
        behaviour,
        indexedDB: {
            deleteDatabase(name) {
                attempts.push(name);
                const request = { onsuccess: null, onerror: null, onblocked: null, error: null };
                setImmediate(() => {
                    const mode = behaviour.get(name);
                    if (mode === 'silent') return;
                    if (mode === 'blocked') { if (request.onblocked) request.onblocked(); return; }
                    if (mode === 'error') {
                        request.error = new Error('Deletion failed');
                        if (request.onerror) request.onerror();
                        return;
                    }
                    databases.delete(name);
                    if (request.onsuccess) request.onsuccess();
                });
                return request;
            },
            databases: async () => [...databases].map((name) => ({ name, version: 1 })),
            /** Enough of open() for the storage probe: one object store, put, and a completing transaction. */
            open(name) {
                attempts.push('open:' + name);
                const request = { result: null, error: null, onupgradeneeded: null, onsuccess: null, onerror: null };
                if (behaviour.get('open') === 'silent') return request;
                setImmediate(() => {
                    const fresh = !databases.has(name);
                    databases.add(name);
                    const stores = new Set();
                    request.result = {
                        objectStoreNames: { contains: (store) => stores.has(store) },
                        createObjectStore(store) { stores.add(store); },
                        transaction() {
                            const transaction = { oncomplete: null, onerror: null, onabort: null,
                                objectStore: () => ({ put: () => ({}) }) };
                            setImmediate(() => { if (transaction.oncomplete) transaction.oncomplete(); });
                            return transaction;
                        },
                        close() {}
                    };
                    if (fresh && request.onupgradeneeded) request.onupgradeneeded();
                    if (request.onsuccess) request.onsuccess();
                });
                return request;
            }
        }
    };
}

/**
 * navigator.locks with the given held lock names (a name, or 'name@client' for the page that holds it); busy makes
 * the maintenance lock unavailable.
 */
function fakeLocks(held = [], { busy = false } = {}) {
    const names = new Set(held);
    const requests = [];
    return {
        held: names,
        requests,
        request(name, options, callback) {
            requests.push({ name, options });
            return Promise.resolve(callback(busy && options && options.ifAvailable ? null : { name }));
        },
        query: async () => ({ held: [...names].map((entry) => {
            const [name, clientId] = entry.split('@');
            return { name, mode: 'exclusive', clientId: clientId || 'client-' + name };
        }), pending: [] })
    };
}

function environment({ databases = [], held = [], busy = false, locks = true, visibility = 'visible',
    now = NOW } = {}) {
    const storage = mapStorage();
    const idb = fakeIndexedDB(databases);
    const navigatorLocks = locks ? fakeLocks(held, { busy }) : undefined;
    const document = { visibilityState: visibility };
    const clock = { now };
    const options = {
        indexedDB: idb.indexedDB, locks: navigatorLocks, storage, document, now: () => clock.now,
        storageTimeout: 50
    };
    return { storage, idb, locks: navigatorLocks, document, clock, options };
}

test('maintenance does nothing in a hidden tab', async () => {
    const { api } = loadApi();
    const env = environment({ visibility: 'hidden' });
    register(env.storage, 'rows-a', { created: NOW - 5 * DAY, used: NOW - 5 * DAY, bytes: 10, dispose: true });
    const report = await api.maintainRowStores(env.options);
    assert.equal(report.skipped, 'hidden');
    assert.deepEqual(env.idb.attempts, []);
    assert.deepEqual(env.locks.requests, [], 'a hidden tab does not even ask for the maintenance lock');
    assert.notEqual(entryOf(env.storage, 'rows-a'), null);
});

test('maintenance runs in one tab at a time', async () => {
    const { api } = loadApi();
    const env = environment({ busy: true });
    register(env.storage, 'rows-a', { created: NOW, used: NOW, bytes: 10, dispose: true });
    const report = await api.maintainRowStores(env.options);
    assert.equal(report.skipped, 'busy');
    assert.equal(env.locks.requests[0].name, 'rdf4j-workbench-row-store-maintenance');
    assert.equal(env.locks.requests[0].options.ifAvailable, true);
    assert.deepEqual(env.idb.attempts, []);
});

test('maintenance deletes stores flagged for cleanup unless a page still holds them', async () => {
    const { api } = loadApi();
    const env = environment({ databases: [DATABASE + 'rows-a', DATABASE + 'rows-b', DATABASE + 'rows-c'],
        held: [LOCK + 'rows-b'] });
    register(env.storage, 'rows-a', { created: NOW - HOUR, used: NOW - HOUR, bytes: 10, dispose: true });
    register(env.storage, 'rows-b', { created: NOW - HOUR, used: NOW - HOUR, bytes: 10, dispose: true });
    register(env.storage, 'rows-c', { created: NOW - HOUR, used: NOW - HOUR, bytes: 10 });
    const report = await api.maintainRowStores(env.options);
    assert.deepEqual([...report.deleted], ['rows-a']);
    assert.deepEqual(env.idb.attempts.filter((name) => name.startsWith(DATABASE)), [DATABASE + 'rows-a']);
    assert.equal(entryOf(env.storage, 'rows-a'), null);
    assert.equal(entryOf(env.storage, 'rows-b').dispose, true, 'the held store waits for its page to let go');
    assert.notEqual(entryOf(env.storage, 'rows-c'), null);
});

test('maintenance deletes stores nobody has used for three days, at most once an hour across tabs', async () => {
    const { api } = loadApi();
    const env = environment({ databases: [DATABASE + 'rows-old', DATABASE + 'rows-new', DATABASE + 'rows-held'],
        held: [LOCK + 'rows-held'] });
    register(env.storage, 'rows-old', { created: NOW - 4 * DAY, used: NOW - 4 * DAY, bytes: 10 });
    register(env.storage, 'rows-new', { created: NOW - 2 * DAY, used: NOW - 2 * DAY, bytes: 10 });
    register(env.storage, 'rows-held', { created: NOW - 9 * DAY, used: NOW - 9 * DAY, bytes: 10 });
    const first = await api.maintainRowStores(env.options);
    assert.deepEqual([...first.deleted], ['rows-old']);
    assert.equal(Number(env.storage.getItem(MAINTAINED)), NOW);

    env.clock.now = NOW + HOUR / 2;
    env.idb.databases.add(DATABASE + 'rows-later');
    register(env.storage, 'rows-later', { created: NOW - 5 * DAY, used: NOW - 5 * DAY, bytes: 10 });
    register(env.storage, 'rows-flagged', { created: NOW, used: NOW, bytes: 10, dispose: true });
    const second = await api.maintainRowStores(env.options);
    assert.deepEqual([...second.deleted], ['rows-flagged'], 'within the hour only flagged stores are deleted');
    assert.notEqual(entryOf(env.storage, 'rows-later'), null);

    env.clock.now = NOW + HOUR + 1;
    const third = await api.maintainRowStores(env.options);
    assert.deepEqual([...third.deleted], ['rows-later']);
    assert.notEqual(entryOf(env.storage, 'rows-held'), null, 'a held store is never deleted for its age');
});

test('without Web Locks, maintenance waits thirty days since a store was last used', async () => {
    const { api } = loadApi();
    const env = environment({ locks: false, databases: [DATABASE + 'rows-five', DATABASE + 'rows-forty'] });
    register(env.storage, 'rows-five', { created: NOW - 40 * DAY, used: NOW - 5 * DAY, bytes: 10 });
    register(env.storage, 'rows-forty', { created: NOW - 40 * DAY, used: NOW - 31 * DAY, bytes: 10 });
    const report = await api.maintainRowStores(env.options);
    assert.deepEqual([...report.deleted], ['rows-forty']);
    assert.notEqual(entryOf(env.storage, 'rows-five'), null, 'without Web Locks it may belong to a live page');
});

test('maintenance deletes old store databases nobody registered and forgets entries without a database', async () => {
    const { api } = loadApi();
    const oldId = idAt(NOW - 4 * DAY, 'orphan');
    const youngId = idAt(NOW - HOUR, 'young');
    const heldId = idAt(NOW - 9 * DAY, 'held');
    const env = environment({ databases: [DATABASE + oldId, DATABASE + youngId, DATABASE + heldId, 'unrelated-db'],
        held: [LOCK + heldId] });
    register(env.storage, 'rows-gone', { created: NOW - 2 * HOUR, used: NOW - 2 * HOUR, bytes: 10 });
    register(env.storage, 'rows-fresh', { created: NOW - 1000, used: NOW - 1000, bytes: 10 });
    const report = await api.maintainRowStores(env.options);
    assert.deepEqual([...report.deleted], [oldId]);
    assert.equal(env.idb.attempts.includes('unrelated-db'), false);
    assert.equal(entryOf(env.storage, 'rows-gone'), null, 'an entry whose database is gone is forgotten');
    assert.notEqual(entryOf(env.storage, 'rows-fresh'), null, 'a store being created now keeps its entry');
});

test('maintenance keeps stored results under the cap, least recently used first', async () => {
    const { api } = loadApi();
    assert.equal(api.ROW_STORE_CAP_BYTES, 50000000000);
    const env = environment({ held: [LOCK + 'rows-held'],
        databases: [DATABASE + 'rows-oldest', DATABASE + 'rows-held', DATABASE + 'rows-recent'] });
    register(env.storage, 'rows-oldest', { created: NOW - 3 * HOUR, used: NOW - 3 * HOUR, bytes: 60 });
    register(env.storage, 'rows-held', { created: NOW - 4 * HOUR, used: NOW - 4 * HOUR, bytes: 50 });
    register(env.storage, 'rows-recent', { created: NOW - HOUR, used: NOW - HOUR, bytes: 40 });
    const report = await api.maintainRowStores(Object.assign({ capBytes: 100 }, env.options));
    assert.deepEqual([...report.deleted], ['rows-oldest'], 'deleting the oldest unheld store gets under the cap');
    assert.notEqual(entryOf(env.storage, 'rows-held'), null);
    assert.notEqual(entryOf(env.storage, 'rows-recent'), null);
});

test('maintenance deletes the old shared database once no tab runs the old Workbench', async () => {
    const { api } = loadApi();
    const env = environment({ databases: [LEGACY_DATABASE], held: [LEGACY_LOCK + 'rows-old-tab'] });
    env.storage.setItem(LEGACY_MARKER + 'rows-old-1', 'pending');
    await api.maintainRowStores(env.options);
    assert.equal(env.storage.getItem(LEGACY_MARKER + 'rows-old-1'), null, 'the old markers are dropped');
    assert.equal(env.idb.attempts.includes(LEGACY_DATABASE), false, 'an old tab still uses it');

    env.locks.held.clear();
    await api.maintainRowStores(env.options);
    assert.equal(env.idb.attempts.includes(LEGACY_DATABASE), true);
    assert.equal(env.idb.databases.has(LEGACY_DATABASE), false);
});

test('a deletion that browser storage blocks or leaves unanswered stays flagged for a later run', async () => {
    const { api } = loadApi();
    const env = environment({ databases: [DATABASE + 'rows-blocked', DATABASE + 'rows-silent'] });
    env.idb.behaviour.set(DATABASE + 'rows-blocked', 'blocked');
    env.idb.behaviour.set(DATABASE + 'rows-silent', 'silent');
    register(env.storage, 'rows-blocked', { created: NOW, used: NOW, bytes: 10, dispose: true });
    register(env.storage, 'rows-silent', { created: NOW, used: NOW, bytes: 10, dispose: true });
    const started = Date.now();
    const report = await api.maintainRowStores(env.options);
    assert.ok(Date.now() - started < 2000, 'maintenance does not wait on browser storage beyond its time limit');
    assert.deepEqual([...report.deleted], []);
    assert.equal(entryOf(env.storage, 'rows-blocked').dispose, true);
    assert.equal(entryOf(env.storage, 'rows-silent').dispose, true);
});

test('maintenance stops when its tab is hidden midway', async () => {
    const { api } = loadApi();
    const env = environment({ databases: [DATABASE + 'rows-a', DATABASE + 'rows-b'] });
    register(env.storage, 'rows-a', { created: NOW, used: NOW, bytes: 10, dispose: true });
    register(env.storage, 'rows-b', { created: NOW, used: NOW, bytes: 10, dispose: true });
    const deleteDatabase = env.idb.indexedDB.deleteDatabase;
    env.idb.indexedDB.deleteDatabase = (name) => {
        env.document.visibilityState = 'hidden';
        return deleteDatabase(name);
    };
    const report = await api.maintainRowStores(env.options);
    assert.equal(report.deleted.length, 1);
    assert.equal(env.idb.attempts.filter((name) => name.startsWith(DATABASE)).length, 1);
});

test('scheduled maintenance runs after a delay, when the tab is shown, and when a store is flagged', async () => {
    const windowListeners = new Map();
    const { api, window } = loadApi({
        addEventListener(type, listener) {
            windowListeners.set(type, [...(windowListeners.get(type) || []), listener]);
        }
    });
    const documentListeners = new Map();
    const env = environment({ databases: [DATABASE + 'rows-a', DATABASE + 'rows-b', DATABASE + 'rows-c'] });
    env.document.addEventListener = (type, listener) => {
        documentListeners.set(type, [...(documentListeners.get(type) || []), listener]);
    };
    env.options.delay = 5;
    const settle = () => new Promise((resolve) => setTimeout(resolve, 60));

    register(env.storage, 'rows-a', { created: NOW, used: NOW, bytes: 10, dispose: true });
    api.scheduleRowStoreMaintenance(env.options);
    await settle();
    assert.deepEqual(env.idb.attempts.filter((name) => name.startsWith(DATABASE)), [DATABASE + 'rows-a']);

    env.document.visibilityState = 'hidden';
    register(env.storage, 'rows-b', { created: NOW, used: NOW, bytes: 10, dispose: true });
    for (const listener of windowListeners.get('storage') || []) {
        listener({ key: REGISTRY + 'rows-b', newValue: env.storage.getItem(REGISTRY + 'rows-b') });
    }
    await settle();
    assert.equal(env.idb.attempts.includes(DATABASE + 'rows-b'), false, 'a hidden tab leaves it to a visible one');

    env.document.visibilityState = 'visible';
    for (const listener of documentListeners.get('visibilitychange') || []) listener({ type: 'visibilitychange' });
    await settle();
    assert.equal(env.idb.attempts.includes(DATABASE + 'rows-b'), true, 'it runs when the tab is shown again');

    register(env.storage, 'rows-c', { created: NOW, used: NOW, bytes: 10, dispose: true });
    for (const listener of windowListeners.get('storage') || []) {
        listener({ key: 'unrelated', newValue: 'x' });
        listener({ key: REGISTRY + 'rows-c', newValue: env.storage.getItem(REGISTRY + 'rows-c') });
    }
    await settle();
    assert.equal(env.idb.attempts.includes(DATABASE + 'rows-c'), true, 'another tab flagging a store starts it');
    assert.ok(window, 'the module listened on its window');
});

// Where Web Locks are unavailable, a live page keeps its stored results from cleanup by marking them used every half
// hour; like all IndexedDB-related work, only while the page is visible (and it writes only to localStorage).
test('a page marks its stored results used only while it is visible', async () => {
    const { MemoryWorker } = require('./query-load-more-harness.js');
    const { api, window } = loadApi();
    const store = await api.createRowStore({ workerFactory: () => new MemoryWorker(), spillRowLimit: 0 });
    await store.append([[null]]);
    for (let index = 0; index < 100 && store.inMemory; index++) await new Promise((resolve) => setImmediate(resolve));
    const key = REGISTRY + store.id;
    const old = Date.now() - 5 * DAY;
    window.localStorage.setItem(key, JSON.stringify(Object.assign(JSON.parse(window.localStorage.getItem(key)),
        { used: old })));
    api.touchCurrentRowStores({ visibilityState: 'hidden' });
    assert.equal(JSON.parse(window.localStorage.getItem(key)).used, old, 'a hidden page touches nothing');
    api.touchCurrentRowStores({ visibilityState: 'visible' });
    assert.ok(JSON.parse(window.localStorage.getItem(key)).used > old);
    await store.dispose();
});

// The button in a storage error: deletes what the Workbench can delete itself, and says what it cannot.
test('resetting browser storage deletes the old database and every stored result no page holds', async () => {
    const { api } = loadApi();
    const env = environment({ databases: [LEGACY_DATABASE, DATABASE + 'rows-free', DATABASE + 'rows-held',
        DATABASE + 'rows-unregistered'], held: [LOCK + 'rows-held', LEGACY_LOCK + 'rows-a@old-1',
        LEGACY_LOCK + 'rows-b@old-1', LEGACY_LOCK + 'rows-c@old-2'] });
    register(env.storage, 'rows-free', { created: NOW, used: NOW, bytes: 10 });
    register(env.storage, 'rows-held', { created: NOW, used: NOW, bytes: 10 });
    register(env.storage, 'rows-gone', { created: NOW - HOUR, used: NOW - HOUR, bytes: 10 });
    env.storage.setItem(LEGACY_MARKER + 'rows-old', 'pending');
    env.storage.setItem(MAINTAINED, String(NOW));
    const report = await api.resetRowStorage(env.options);
    assert.equal(report.legacyDeleted, true, 'the old database is deleted even while old pages use it');
    assert.equal(env.idb.databases.has(LEGACY_DATABASE), false);
    assert.deepEqual([...report.deleted].sort(), ['rows-free', 'rows-gone', 'rows-unregistered']);
    assert.deepEqual([...report.kept], ['rows-held'], 'a store an open page shows is kept');
    assert.equal(report.olderPages, 2, 'two pages of the old Workbench still hold storage');
    assert.equal(report.storageAnswers, true);
    assert.equal(env.storage.getItem(LEGACY_MARKER + 'rows-old'), null);
    assert.equal(env.storage.getItem(MAINTAINED), null);
    assert.equal(entryOf(env.storage, 'rows-free'), null);
    assert.notEqual(entryOf(env.storage, 'rows-held'), null);
    assert.deepEqual([...env.idb.databases].filter((name) => name.startsWith('rdf4j-workbench')),
        [DATABASE + 'rows-held'], 'the probe database is deleted again');
});

test('a reset says so when browser storage still does not answer', async () => {
    const { api } = loadApi();
    const env = environment({ databases: [LEGACY_DATABASE] });
    env.idb.behaviour.set(LEGACY_DATABASE, 'blocked');
    env.idb.behaviour.set('open', 'silent');
    const started = Date.now();
    const report = await api.resetRowStorage(env.options);
    assert.ok(Date.now() - started < 2000, 'the reset does not wait on browser storage beyond its time limit');
    assert.equal(report.legacyDeleted, false, 'another tab still holds the old database');
    assert.equal(report.storageAnswers, false);
    assert.equal(report.olderPages, 0);
});
